<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= esc($title) ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head>
<body class="bg-light"><main class="container py-4"><div class="card shadow-sm mx-auto" style="max-width:800px"><div class="card-body"><h2 class="text-primary"><?= esc($title) ?></h2><form method="post" action="<?= esc($formAction) ?>" class="row g-3">
<?php $fields = [['account_number','Account Number'],['customer_name','Customer Name'],['address','Address'],['phone','Phone'],['email','Email'],['meter_number','Meter Number']]; foreach ($fields as [$name,$label]): ?><div class="col-md-<?= $name === 'address' ? '12' : '6' ?>"><label class="form-label"><?= $label ?></label><?php if ($name === 'address'): ?><textarea class="form-control" name="<?= $name ?>" required><?= esc($account[$name] ?? '') ?></textarea><?php else: ?><input class="form-control" name="<?= $name ?>" value="<?= esc($account[$name] ?? '') ?>" <?= in_array($name, ['account_number','customer_name']) ? 'required' : '' ?>><?php endif; ?></div><?php endforeach; ?>
<div class="col-md-6"><label class="form-label">Connection Type</label><select class="form-select" name="connection_type"><?php foreach(['residential','commercial','industrial'] as $v): ?><option value="<?= $v ?>" <?= ($account['connection_type'] ?? 'residential') === $v ? 'selected' : '' ?>><?= ucfirst($v) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active','inactive','suspended'] as $v): ?><option value="<?= $v ?>" <?= ($account['status'] ?? 'active') === $v ? 'selected' : '' ?>><?= ucfirst($v) ?></option><?php endforeach; ?></select></div><div class="col-12"><button class="btn btn-primary">Save Account</button> <a class="btn btn-secondary" href="<?= base_url('dashboard') ?>">Cancel</a></div></form></div></div></main></body></html>
